import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"文件格式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/file-formats.md","filePath":"zh/reference/file-formats.md","lastUpdated":1793314357000}'),i={name:"zh/reference/file-formats.md"};function r(o,e,l,p,c,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="文件格式" tabindex="-1">文件格式 <a class="header-anchor" href="#文件格式" aria-label="Permalink to &quot;文件格式&quot;">​</a></h1><p>本页说明练习模式可以导入的文件及示例。文件可以是 UTF-8（带或不带 BOM）、UTF-16 或 GBK 等旧编码，MeetCue 会自动识别；Windows 和 Unix 换行符都支持。</p><h2 id="字幕-srt" tabindex="-1">字幕：SRT <a class="header-anchor" href="#字幕-srt" aria-label="Permalink to &quot;字幕：SRT&quot;">​</a></h2><p>标准 SubRip 文件。在文本开头写说话人名字，后接冒号。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1</span></span>
<span class="line"><span>00:00:01,200 --&gt; 00:00:04,800</span></span>
<span class="line"><span>面试官：先请你简单介绍一下自己？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>00:00:05,500 --&gt; 00:00:12,000</span></span>
<span class="line"><span>小林：好的。我做数据中心网络八年了。</span></span></code></pre></div><p>毫秒前的分隔符用逗号或点号都可以。</p><h2 id="字幕-webvtt" tabindex="-1">字幕：WebVTT <a class="header-anchor" href="#字幕-webvtt" aria-label="Permalink to &quot;字幕：WebVTT&quot;">​</a></h2><p>说话人取自 <code>&lt;v 名字&gt;</code> 标签或“名字：”前缀。小时部分可以省略。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WEBVTT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>00:01.200 --&gt; 00:04.800</span></span>
<span class="line"><span>&lt;v 面试官&gt;先请你简单介绍一下自己？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>00:05.500 --&gt; 00:12.000</span></span>
<span class="line"><span>&lt;v 小林&gt;好的。我做数据中心网络八年了。</span></span></code></pre></div><h2 id="字幕-纯文本" tabindex="-1">字幕：纯文本 <a class="header-anchor" href="#字幕-纯文本" aria-label="Permalink to &quot;字幕：纯文本&quot;">​</a></h2><p>每行一句，可以带“名字：”前缀，也可以在方括号中带时间戳。全角冒号（<code>：</code>）和半角冒号都可以。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[00:01] 面试官：先请你简单介绍一下自己？</span></span>
<span class="line"><span>[00:05] 小林：好的。我做数据中心网络八年了。</span></span></code></pre></div><p>没有时间戳时，MeetCue 逐句依次播放。没有说话人时，由模型把每句标为提问或回答，你确认后再使用。</p><h2 id="问题列表-文本与-markdown" tabindex="-1">问题列表：文本与 Markdown <a class="header-anchor" href="#问题列表-文本与-markdown" aria-label="Permalink to &quot;问题列表：文本与 Markdown&quot;">​</a></h2><p>每行一题。以 <code>#</code> 开头的行开始一个分组，分组名会显示在预览和复盘中。空行会被忽略，Markdown 列表符号（<code>-</code>、<code>*</code>、<code>1.</code>）会被去掉。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 基础</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 控制平面和数据平面有什么区别？</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BGP 如何选择最优路径？</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 设计</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 如果要为两个数据中心设计网络，你会怎么做？</span></span></code></pre></div><h2 id="问题列表-csv" tabindex="-1">问题列表：CSV <a class="header-anchor" href="#问题列表-csv" aria-label="Permalink to &quot;问题列表：CSV&quot;">​</a></h2><p>第一行是列名。只有 <code>question</code> 是必填的。</p><table tabindex="0"><thead><tr><th>列</th><th>含义</th></tr></thead><tbody><tr><td><code>question</code></td><td>问题</td></tr><tr><td><code>reference_answer</code></td><td>参考回答，用于复盘反馈</td></tr><tr><td><code>category</code></td><td>分组名</td></tr><tr><td><code>followups</code></td><td>追问，用 <code>|</code> 分隔</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>question,reference_answer,category,followups</span></span>
<span class="line"><span>&quot;什么是 SDN？&quot;,&quot;控制与转发分离；集中控制器；通过 API 编程。&quot;,基础,&quot;你用过哪些控制器？|有哪些风险？&quot;</span></span></code></pre></div><h2 id="示例文件" tabindex="-1">示例文件 <a class="header-anchor" href="#示例文件" aria-label="Permalink to &quot;示例文件&quot;">​</a></h2><ul><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/practice/sdn-interview.srt" target="_blank" rel="noreferrer">sdn-interview.srt</a>：一段中英混合的简短面试。</li><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/practice/questions-network.csv" target="_blank" rel="noreferrer">questions-network.csv</a>：十道网络架构面试题，附参考回答。</li><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/practice/questions-software-engineer.csv" target="_blank" rel="noreferrer">questions-software-engineer.csv</a>：十四道软件工程面试题，附参考回答和追问（英文）。</li><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/practice/swe-interview.srt" target="_blank" rel="noreferrer">swe-interview.srt</a>：一场后端软件工程师技术面（英文）。</li><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/practice/questions-security-ai.csv" target="_blank" rel="noreferrer">questions-security-ai.csv</a>：十二道网络安全与 AI 安全面试题，附参考回答和追问（英文）。</li><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/practice/security-ai-interview.srt" target="_blank" rel="noreferrer">security-ai-interview.srt</a>：一场 AI 平台团队的网络安全工程师面试（英文）。</li><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/practice/questions-software-engineer-zh.csv" target="_blank" rel="noreferrer">questions-software-engineer-zh.csv</a>：十四道后端开发面试题，附参考回答和追问（中文）。</li><li><a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/practice/questions-network-operations-zh.csv" target="_blank" rel="noreferrer">questions-network-operations-zh.csv</a>：四十二道运营商网络运维场景题，分七组，附参考回答和追问（中文）。</li></ul><p>其中四个已内置在 MeetCue 中：<code>questions-software-engineer.csv</code>、<code>questions-security-ai.csv</code>、<code>questions-software-engineer-zh.csv</code> 和 <code>questions-network-operations-zh.csv</code>。在模拟面试窗口中点 <strong>使用</strong> 即可，其余文件用 <strong>选择文件…</strong> 载入。见<a href="/meetcue/zh/guide/mock-interview">模拟面试</a>。</p>`,23)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
